1. import { WalletService } from "./service/wallet-service";
2. import type { IWalletService } from "./service/wallet-service.interface";
3. import type { TUserId } from "@/types";
4. import { tryCatch } from "@/lib/try-catch-wrapper";
5. import { UserModule } from "../user";
6. 
7. export const walletPlayground = async () => {
8.   const walletService = new WalletService();
9.   const userService = new UserModule();
10. 
11.   tryCatch({
12.     ctx: async () => {
13.       // Use unique emails so the playground is re-runnable
14.       const suffix = Date.now();
15.       const alice = await userService.createUser(`alice+${suffix}@example.com`, "Alice", "password123");
16.       if (!alice) throw new Error("Failed to create Alice");
17. 
18.       const bob = await userService.createUser(`bob+${suffix+45646}@example.com`, "Bob", "password123");
19.       if (!bob) throw new Error("Failed to create Bob");
20.       
21.       const accountA = await walletService.createAccount({
22.         userId: alice.id,
23.         name: "Alice's Checking",
24.         accountNumber: `ACC-A-${suffix}`,
25.         balance: 1000,
26.       });
27.       if (!accountA) throw new Error("Failed to create Alice's account");
28.       
29.       const accountB = await walletService.createAccount({
30.         userId: bob.id,
31.         name: "Bob's Savings",
32.         accountNumber: `ACC-B-${suffix}`,
33.         balance: 500,
34.       });
35.       if (!accountB) throw new Error("Failed to create Bob's account");
36.       
37.       console.log("Created Accounts:", accountA, accountB);
38.     
39.       const transfer = await walletService.transfer({
40.         amount: 200,
41.         senderAccountId: accountA.id,
42.         userId: accountA.userId,
43.         senderName: accountA.name,
44.         receiverAccountId: accountB.id,
45.         receiverName: accountB.name,
46.         createdAt: new Date(),
47.       });
48.       console.log("Transfer-01 completed:", transfer);
49. 
50.       setTimeout(async () => {
51.         // Second transfer to test multiple transactions and ledger entries
52.         const transfer2 = await walletService.transfer({
53.           amount: 150,
54.           senderAccountId: accountA.id,
55.           userId: accountA.userId,
56.           senderName: accountA.name,
57.           receiverAccountId: accountB.id,
58.           receiverName: accountB.name,
59.           createdAt: new Date(),
60.         });
61.         console.log("Transfer-02 completed:", transfer2);
62.       }, 2000);
63. 
64.       const updatedAccountA = await walletService.getAccountById(accountA.id);
65.       const updatedAccountB = await walletService.getAccountById(accountB.id);
66.       console.log("Updated Account A:", updatedAccountA);
67.       console.log("Updated Account B:", updatedAccountB);
68. 
69.       // Third transfer to fromm Bob to Alice
70.       const transfer3 = await walletService.transfer({
71.         amount: 50,
72.         senderAccountId: accountB.id,
73.         userId: accountB.userId,
74.         senderName: accountB.name,
75.         receiverAccountId: accountA.id,
76.         receiverName: accountA.name,
77.         createdAt: new Date(),
78.       });
79.       console.log("Transfer-03 completed:", transfer3);
80. 
81.       // 
82.     },
83.     errorMessage: "Error in wallet playground",
84.   })
85. };
86. 
87. walletPlayground();

