import { WalletService } from "./service/wallet-service";
import type { IWalletService } from "./service/wallet-service.interface";
import type { TUserId } from "@/types";
import { tryCatch } from "@/lib/try-catch-wrapper";
import { UserModule } from "../user";

export const walletPlayground = async () => {
  const walletService = new WalletService();
  const userService = new UserModule();

  tryCatch({
    ctx: async () => {
      // Use unique emails so the playground is re-runnable
      const suffix = Date.now();
      const alice = await userService.createUser(`alice+${suffix}@example.com`, "Alice", "password123");
      if (!alice) throw new Error("Failed to create Alice");

      const bob = await userService.createUser(`bob+${suffix+45646}@example.com`, "Bob", "password123");
      if (!bob) throw new Error("Failed to create Bob");

      const accountA = await walletService.createAccount({
        userId: alice.id,
        name: "Alice's Checking",
        accountNumber: `ACC-A-${suffix}`,
        balance: 1000,
      });
      if (!accountA) throw new Error("Failed to create Alice's account");

      const accountB = await walletService.createAccount({
        userId: bob.id,
        name: "Bob's Savings",
        accountNumber: `ACC-B-${suffix}`,
        balance: 500,
      });
      if (!accountB) throw new Error("Failed to create Bob's account");

      console.log("Created Accounts:", accountA, accountB);

      const transfer = await walletService.transfer({
        amount: 200,
        senderAccountId: accountA.id,
        userId: accountA.userId,
        senderName: accountA.name,
        receiverAccountId: accountB.id,
        receiverName: accountB.name,
        createdAt: new Date(),
      });
      console.log("Transfer-01 completed:", transfer);

      await new Promise((resolve) => setTimeout(resolve, 2000));

      // Second transfer to test multiple transactions and ledger entries
      const transfer2 = await walletService.transfer({
        amount: 150,
        senderAccountId: accountA.id,
        userId: accountA.userId,
        senderName: accountA.name,
        receiverAccountId: accountB.id,
        receiverName: accountB.name,
        createdAt: new Date(),
      });
      console.log("Transfer-02 completed:", transfer2);

      const updatedAccountA = await walletService.getAccountById(accountA.id);
      const updatedAccountB = await walletService.getAccountById(accountB.id);
      console.log("Updated Account A:", updatedAccountA);
      console.log("Updated Account B:", updatedAccountB);

      // Third transfer to fromm Bob to Alice
      const transfer3 = await walletService.transfer({
        amount: 50,
        senderAccountId: accountB.id,
        userId: accountB.userId,
        senderName: accountB.name,
        receiverAccountId: accountA.id,
        receiverName: accountA.name,
        createdAt: new Date(),
      });
      console.log("Transfer-03 completed:", transfer3);

      // 
    },
    errorMessage: "Error in wallet playground",
  })
};

