4. import { db } from "@/modules/database/client";
5. import { eq, sql } from "drizzle-orm";
6. 
7. export class TransactionRepository implements ITransactionRepository {
8.   async save(transaction: ITransactionDBDTO): Promise<void> {
9.     return tryCatch({
10.       ctx: async () => {
11.         await db
12.           .transaction(
13.             async (tx) => {
14.               // 1. Insert the transaction.
15.               await tx.insert(TransactionsTable)
16.                 .values({
17.                 ...transaction,
18.                 amount: BigInt(transaction.amount),
19.                 status: "pending", // Always set new transactions to pending
20.                 createdAt: new Date(),
21.                 updatedAt: new Date(),
22.                 });
23.             }
24.           )
25.       }
26.     });
27.   };
28. 
29.   // If the transaction is successful, update the record with status "success". 
30.   // If the transaction is in pending state for too long or fails, 
31.   // update the record with status "failed" with a cron job.
32.   async update(transaction: ITransactionDBDTO): Promise<ITransactionDBDTO> {
33.     return tryCatch({
34.       ctx: async () => {
35.         const [updatedTransaction] = await db.update(TransactionsTable)
36.           .set({
37.             ...transaction,
38.             amount: BigInt(transaction.amount),
39.             updatedAt: new Date(),
40.           })
41.           .where(eq(TransactionsTable.id, transaction.id))
42.           .returning();
43. 
44.         if (!updatedTransaction) {
45.           throw new Error(`Failed to update transaction with id: ${transaction.id}`);
46.         }
47. 
48.         return updatedTransaction
49.       }
50.     })
51.   };
52. 
53.   async findById(transactionId: ITransactionDBDTO["id"]): Promise<ITransactionDBDTO | null> {
54.     return tryCatch({
55.       ctx: async () => {
56.         const transaction = await db.query.TransactionsTable.findFirst({
57.           where: {
58.             id: {
59.               eq: transactionId
60.             },
61.           }
62.         });
63. 
64.         return transaction || null;
65.       }
66.     })
67.   };
68. 
69.   async findByUserId(userId: ITransactionDBDTO["userId"]): Promise<ITransactionDBDTO[]> {
70.     return tryCatch({
71.       ctx: async () => {
72.         const transactions = await db.query.TransactionsTable.findMany({
73.           where: {
74.             userId: {
75.               eq: userId
76.             }
77.           },
78.         });
79.         return transactions;
80.       }
81.     })
82.   };
