102.         
103.         if (dateRange) {
104.           whereClauses.push(
105.             { 
106.               RAW: (table: any) => sql`${table.senderAccountId} = ${accountId} OR ${table.receiverAccountId} = ${accountId}` 
107.             }
108.           );
109.         }
110. 
