25. export class WalletService implements IWalletService {
26.   private readonly accountRepo: IAccountRepository;
27.   private readonly transactionRepo: ITransactionRepository;
28.   private readonly ledgerRepo: ILedgerRepository;
29. 
30.   constructor(
31.     accountRepo?: IAccountRepository,
32.     transactionRepo?: ITransactionRepository,
33.     ledgerRepo?: ILedgerRepository,
34.   ) {
35.     this.accountRepo = accountRepo ?? new AccountRepository();
36.     this.transactionRepo = transactionRepo ?? new TransactionRepository();
37.     this.ledgerRepo = ledgerRepo ?? new LedgerRepository();
38.   }
39. 
40.   createAccount(account: CreateAccountInput): Promise<IAccount> {
41. 
42.     const _idempotencyKey = IdempotencyManager.generateAccountCreationKey(
43.       account.userId.toString(),
44.       account.name,
45.     );
46. 
47.     return tryCatch({
48.       ctx: async () => {
