50.           id: ID.BankAccountId(),
51.           ...account,
52.         });
53.         return newAccount;
54.       },
55.       errorMessage: "FAILED_TO_CREATE_ACCOUNT",
56.     });
57.   }
58. 
59.   getAccountById(accountId: TBankAccountId): Promise<IAccount | null> {
60.     return tryCatch({
61.       ctx: async () => {
62.         return await this.accountRepo.findById(accountId);
63.       },
64.       errorMessage: "FAILED_TO_GET_ACCOUNT",
65.     });
66.   }
67. 
68.   getUserAccounts(userId: TUserId): Promise<IAccount[]> {
69.     return tryCatch({
70.       ctx: async () => {
71.         return await this.accountRepo.findByUserId(userId);
72.       },
73.       errorMessage: "FAILED_TO_GET_USER_ACCOUNTS",
74.     });
75.   }
76. 
77.   getBalance(accountId: TBankAccountId): Promise<number> {
78.     return tryCatch({
79.       ctx: async () => {
80.         const account = await this.accountRepo.checkBalance(accountId);
81.         return account.balance;
82.       },
83.       errorMessage: "FAILED_TO_GET_BALANCE",
84.     });
85.   }
86. 
87.   async transfer(input: TransferInput): Promise<ITransaction> {
88.     const totalAmount = input.amount;
89. 
90.     // Idempotency guard — prevent duplicate transactions
91.     const _idempotencyKey = IdempotencyManager.generateTransactionKey(
92.       input.senderAccountId.toString(),
93.       input.receiverAccountId.toString(),
94.       totalAmount,
95.     );
96. 
97.     return tryCatch({
98.       ctx: async () => {
99.         // Step 1 — Debit sender and credit receiver atomically per account
100.         await this.accountRepo.adjustBalance(input.senderAccountId, -totalAmount);
101.         await this.accountRepo.adjustBalance(input.receiverAccountId, totalAmount);
102. 
103.         // Step 2 — Create transaction record
104.         const transaction: ITransaction = {
105.           id: ID.TransactionId(),
106.           ...input,
107.           status: "pending",
108.         };
