87.   async transfer(input: TransferInput): Promise<ITransaction> {
88.     const totalAmount = input.amount;
89. 
90.     // Idempotency guard — prevent duplicate transactions
91.     const _idempotencyKey = IdempotencyManager.generateTransactionKey(
92.       input.senderAccountId.toString(),
93.       input.receiverAccountId.toString(),
94.       totalAmount,
95.     );
96. 
97.     return tryCatch({
98.       ctx: async () => {
99.         // Step 1 — Debit sender and credit receiver atomically per account
100.         await this.accountRepo.adjustBalance(input.senderAccountId, -totalAmount);
101.         await this.accountRepo.adjustBalance(input.receiverAccountId, totalAmount);
102. 
103.         // Step 2 — Create transaction record
104.         const transaction: ITransaction = {
105.           id: ID.TransactionId(),
106.           ...input,
107.           status: "pending",
108.         };
109. 
110.         await this.transactionRepo.save({
111.           ...transaction,
112.           amount: BigInt(transaction.amount),
113.         });
114. 
115.         // Step 3 — Record ledger entries (double-entry bookkeeping)
116.         await Promise.all([
117.           this.ledgerRepo.create({
118.             transactionId: transaction.id,
119.             amount: totalAmount,
120.             entryType: "debit",
121.           }),
122.           this.ledgerRepo.create({
123.             transactionId: transaction.id,
124.             amount: totalAmount,
125.             entryType: "credit",
126.           }),
127.         ]);
128. 
129.         // Step 4 — Update transaction status to success
130.         const updatedTransaction = await this.transactionRepo.update({
131.           ...transaction,
132.           status: "success",
133.         });
134.         
135.         
136.         return updatedTransaction;
137.       },
138.       errorMessage: "FAILED_TO_TRANSFER",
139.     });
140.   }

