     return tryCatch({
       ctx: async () => {
         const transactions = await db.query.TransactionsTable.findMany({
           where: {
             userId: {
               eq: userId
             }
           },
         });
         return transactions;
       }
     })
   };

   async failedTransactions(
     query: {
       userId: ITransactionDBDTO["userId"], 
