     return tryCatch({
       ctx: async () => {

         if (dateRange) {
           whereClauses.push(
             { 
               RAW: (table: any) => sql`${table.senderAccountId} = ${accountId} OR ${table.receiverAccountId} = ${accountId}` 
             }
           );
         }

         if (accountId) {
           whereClauses.push(
             {
               RAW: (table: any) => sql`${table.senderAccountId} = ${accountId} OR ${table.receiverAccountId} = ${accountId}`
             }
           );
         }

         const transactions = await db.query.TransactionsTable.findMany({
