           offset: 0,
           limit: 10,
           where: {
             AND: [
               ...whereClauses
             ],
             userId: {
               eq: userId
             },
             status: {
               eq: "failed"
             }
           },
         });

         return transactions ?? [];
       }
     });
   };

   async successfulTransactions(query: {
     userId: ITransactionDBDTO["userId"],
