1. import type { IAccountService, IAccount } from "./account-service.interface";
2. import type { TBankAccountId, TUserId } from "@/types";
3. import { tryCatch } from "@/lib/try-catch-wrapper";
4. import { ID } from "@/lib/ID";
5. import { AccountRepository, type IAccountRepository } from "../../../repository";
6. import { IdempotencyManager } from "../../../utils";
7. 
8. export class AccountService implements IAccountService {
9.   private accountRepository: IAccountRepository = new AccountRepository();
10. 
11.   create(account: Omit<IAccount, "id" | "createdAt" | "updatedAt">): Promise<IAccount> {
12.     // Generate idempotency key to prevent duplicate account creation
13.     const idempotencyKey = IdempotencyManager.generateAccountCreationKey(
14.       account.userId.toString(),
15.       account.name
16.     );
17. 
18.     return tryCatch({
19.       ctx: async () => {
20.         const newAccount = await this.accountRepository.create({
21.           id: ID.BankAccountId(),
22.           ...account,
23.         });
24.         return newAccount;
25.       },
26.       errorMessage: "FAILED_TO_CREATE_ACCOUNT",
27.     });
28.   }
29. 
30.   getAccountById(accountId: TBankAccountId): Promise<IAccount | null> {
31.     return tryCatch({
32.       ctx: async () => {
33.         const account = await this.accountRepository.findById(accountId);
34.         return account;
35.       },
36.       errorMessage: "FAILED_TO_GET_ACCOUNT",
37.     });
38.   }
39. 
40.   getUserAccounts(userId: TUserId): Promise<IAccount[]> {
41.     return tryCatch({
42.       ctx: async () => {
43.         const accounts = await this.accountRepository.findByUserId(userId);
44.         return accounts;
45.       },
46.       errorMessage: "FAILED_TO_GET_USER_ACCOUNTS",
47.     });
48.   }
49. 
50.   getBalance(accountId: TBankAccountId): Promise<number> {
51.     return tryCatch({
52.       ctx: async () => {
53.         const account = await this.accountRepository.checkBalance(accountId);
54.         return account.balance;
55.       },
56.       errorMessage: "FAILED_TO_GET_BALANCE",
57.     });
58.   }
59. 
60.   updateAccountBalance(accountId: TBankAccountId, amount: number): Promise<IAccount> {
61.     // Generate idempotency key for balance update
62.     const idempotencyKey = IdempotencyManager.generateBalanceUpdateKey(
63.       accountId.toString(),
64.       amount,
65.       "update"
66.     );
67. 
68.     return tryCatch({
69.       ctx: async () => {
70.         await this.accountRepository.adjustBalance(accountId, amount);
71.         const updatedAccount = await this.accountRepository.findById(accountId);
72.         if (!updatedAccount) {
73.           throw new Error("Failed to retrieve updated account");
74.         }
75.         
76.         return updatedAccount;
77.       },
78.       errorMessage: "FAILED_TO_UPDATE_ACCOUNT_BALANCE",
79.     });
80.   }
81. }
