2. import type { ILedger } from "./ledger-service.interface";
3. 
4. const { createMock, findByTransactionIdMock } = vi.hoisted(() => ({
5.   createMock: vi.fn(),
6.   findByTransactionIdMock: vi.fn(),
7. }));
8. 
9. vi.mock("@/lib/try-catch-wrapper", () => ({
10.   tryCatch: async ({ ctx, errorMessage }: { ctx: () => Promise<any>, errorMessage: string }) => {
11.     try {
12.       return await ctx();
13.     } catch (error) {
14.       console.error(errorMessage, error);
15.       throw error;
16.     }
17.   },
18. }));
19. 
20. vi.mock("../../repository", () => ({
21.   LedgerRepo: function LedgerRepoMock(this: {
22.     create: typeof createMock;
23.     findByTransactionId: typeof findByTransactionIdMock;
24.   }) {
25.     this.create = createMock;
26.     this.findByTransactionId = findByTransactionIdMock;
27.   },
28. }));
