44.   beforeEach(() => {
45.     vi.clearAllMocks();
46.     ledgerService = new LedgerService();
47.   });
48. 
49.   afterEach(() => {
50.     vi.restoreAllMocks();
51.   });
52. 
53.   describe("createEntry", () => {
54.     it("should create a debit entry", async () => {
55.       createMock.mockResolvedValue(mockEntry);
56. 
57.       const result = await ledgerService.createEntry("tx_123" as any, 1000, "debit");
58. 
59.       expect(result).toEqual(mockEntry);
60.       expect(result.amount).toBe(1000);
61.       expect(typeof result.amount).toBe("number");
62.     });
63. 
