       expect(result).toHaveLength(1);
       expect(result[0].status).toBe("failed");
       expect(result[0].amount).toBe(BigInt(1000));
     });

     it("should apply date range filter", async () => {
       const dateRange = {
         from: new Date("2024-01-01"),
